```java
public class SgfParsing {

    private String input;
    private int pos;

    public SgfNode parse(String input) throws SgfParsingException {
        this.input = input;
        this.pos = 0;
        SgfNode root = parseTree();
        if (pos != input.length()) {
            throw new SgfParsingException("unexpected trailing input");
        }
        return root;
    }

    private SgfNode parseTree() throws SgfParsingException {
        expect('(');
        if (pos >= input.length() || input.charAt(pos) != ';') {
            throw new SgfParsingException("tree with no nodes");
        }
        SgfNode node = parseNode();
        while (pos < input.length() && input.charAt(pos) == '(') {
            node.appendChild(parseTree());
        }
        expect(')');
        return node;
    }

    private SgfNode parseNode() throws SgfParsingException {
        expect(';');
        SgfNode node = new SgfNode();
        while (pos < input.length() && input.charAt(pos) != ';' && input.charAt(pos) != '(' && input.charAt(pos) != ')') {
            parseProperty(node);
        }
        return node;
    }

    private void parseProperty(SgfNode node) throws SgfParsingException {
        int start = pos;
        while (pos < input.length() && Character.isUpperCase(input.charAt(pos))) {
            pos++;
        }
        int keyEnd = pos;
        if (keyEnd == start) {
            throw new SgfParsingException("property key must be uppercase");
        }
        String key = input.substring(start, keyEnd);
        Map<String, List<String>> props = node.getProperties(); // need getter
        List<String> values = new ArrayList<>();
        while (pos < input.length() && input.charAt(pos) == '[') {
            pos++; // skip [
            values.add(parseValue());
        }
        if (values.isEmpty()) {
            throw new SgfParsingException("property must have at least one value");
        }
        props.computeIfAbsent(key, k -> new ArrayList<>()).addAll(values);
    }

    private String parseValue() throws SgfParsingException {
        StringBuilder sb = new StringBuilder();
        while (pos < input.length()) {
            char c = input.charAt(pos);
            if (c == ']') {
                pos++;
                return sb.toString();
            }
            if (c == '\\') {
                pos++;
                if (pos >= input.length()) {
                    throw new SgfParsingException("unterminated escape");
                }
                char e = input.charAt(pos);
                if (e == '\n') {
                    // removed
                } else if (Character.isWhitespace(e)) {
                    sb.append(' ');
                } else {
                    sb.append(e);
                }
                pos++;
            } else {
                if (c == '\n') {
                    sb.append('\n');
                } else if (Character.isWhitespace(c)) {
                    sb.append(' ');
                } else {
                    sb.append(c);
                }
                pos++;
            }
        }
        throw new SgfParsingException("unterminated value");
    }

    private void expect(char c) throws SgfParsingException {
        if (pos >= input.length() || input.charAt(pos) != c) {
            throw new SgfParsingException("expected '" + c + "'");
        }
        pos++;
    }
}
